import argparse
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import json
from pathlib import Path
import sqlite3
from datetime import datetime

ASSETS = Path(__file__).resolve().parent


def create_server(host='127.0.0.1', port=8080):
    class Handler(BaseHTTPRequestHandler):
        def log_message(self, *_):
            pass

        def reply(self, value, status=200, content_type='application/json; charset=utf-8'):
            content = value if isinstance(value, bytes) else json.dumps(value).encode('utf-8')
            self.send_response(status)
            self.send_header('Content-Type', content_type)
            self.send_header('Content-Length', str(len(content)))
            self.send_header('X-Content-Type-Options', 'nosniff')
            self.end_headers()
            self.wfile.write(content)

        def do_GET(self):
            if self.path == '/health':
                return self.reply({'status': 'ok'})
            assets = {'/': ('index.html', 'text/html; charset=utf-8'), '/style.css': ('style.css', 'text/css; charset=utf-8')}
            if self.path in assets:
                filename, content_type = assets[self.path]
                return self.reply((ASSETS / filename).read_bytes(), content_type=content_type)
            if self.path == '/api/wins':
                # Parse query parameters
                from urllib.parse import parse_qs, urlparse
                parsed = urlparse(self.path)
                params = parse_qs(parsed.query)
                filter_value = params.get('filter', [None])[0]

                with sqlite3.connect('wins.db') as conn:
                    if filter_value == 'today':
                        today = datetime.now().strftime('%Y-%m-%d')
                        cursor = conn.execute('''SELECT id, title, note, created_at FROM wins
                                                WHERE DATE(created_at) = ?
                                                ORDER BY created_at DESC''', (today,))
                        wins = [dict(row) for row in cursor.fetchall()]
                        count = sum(1 for _ in wins)
                    else:
                        cursor = conn.execute('SELECT id, title, note, created_at FROM wins ORDER BY created_at DESC')
                        wins = [dict(row) for row in cursor.fetchall()]
                        count = sum(1 for _ in wins)
                response = {'wins': wins, 'count': count}
                return self.reply(response)
            return self.reply({'error': 'Not found'}, 404)

        def do_POST(self):
            if self.path == '/api/wins':
                content_length = int(self.headers.get('Content-Length', 0))
                body = self.rfile.read(content_length)
                try:
                    data = json.loads(body)
                except json.JSONDecodeError:
                    return self.reply({'error': 'Invalid JSON'}, 400)

                title = data.get('title')
                note = data.get('note', '')

                if not title or not isinstance(title, str):
                    return self.reply({'error': 'Title is required'}, 400)

                with sqlite3.connect('wins.db') as conn:
                    conn.execute('''INSERT INTO wins (title, note, created_at) 
                                    VALUES (?, ?, ?)''',
                                   (title, note, datetime.now()))
                    conn.commit()

                return self.reply({'status': 'created'}, 201)

        def do_DELETE(self):
            if self.path.startswith('/api/wins/'):
                try:
                    win_id = int(self.path.split('/')[-1])
                except ValueError:
                    return self.reply({'error': 'Invalid ID'}, 400)

                with sqlite3.connect('wins.db') as conn:
                    cursor = conn.execute('SELECT id FROM wins WHERE id = ?', (win_id,))
                    if not cursor.fetchone():
                        return self.reply({'error': 'not found'}, 400)
                    conn.execute('DELETE FROM wins WHERE id = ?', (win_id,))
                    conn.commit()

                return self.reply({'status': 'deleted'}, 200)

        def delete_win(id: int) -> bool:
            with sqlite3.connect('wins.db') as conn:
                cursor = conn.execute('SELECT id FROM wins WHERE id = ?', (id,))
                if not cursor.fetchone():
                    return False
                conn.execute('DELETE FROM wins WHERE id = ?', (id,))
                conn.commit()
            return True

    return ThreadingHTTPServer((host, port), Handler)


def delete_win(id: int) -> bool:
    with sqlite3.connect('wins.db') as conn:
        cursor = conn.execute('SELECT id FROM wins WHERE id = ?', (id,))
        if not cursor.fetchone():
            return False
        conn.execute('DELETE FROM wins WHERE id = ?', (id,))
        conn.commit()
    return True


if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--host', default='127.0.0.1')
    parser.add_argument('--port', type=int, default=8080)
    args = parser.parse_args()
    server = create_server(args.host, args.port)
    with sqlite3.connect('wins.db') as conn:
        conn.execute('''CREATE TABLE IF NOT EXISTS wins
                      (id INTEGER PRIMARY KEY AUTOINCREMENT,
                       title TEXT NOT NULL,
                       note TEXT,
                       created_at DATETIME DEFAULT CURRENT_TIMESTAMP)''')
    server.serve_forever()
